pous.declaration:
FUNCTION_BLOCK MechArm
VAR_INPUT
    ManualMode : BOOL;
    SingleStepMode : BOOL;
    SingleCycleMode : BOOL;
    ContinuousMode : BOOL;
    EmergencyStop : BOOL;
    Start : BOOL;
    DownButton : BOOL;
    UpButton : BOOL;
    LeftButton : BOOL;
    RightButton : BOOL;
    GripButton : BOOL;
    ReleaseButton : BOOL;
    DownLimitSwitch : BOOL;
    UpLimitSwitch : BOOL;
    LeftLimitSwitch : BOOL;
    RightLimitSwitch : BOOL;
    GripLimitSwitch : BOOL;
    ReleaseLimitSwitch : BOOL;
END_VAR
VAR_OUTPUT
    MoveDown : BOOL;
    MoveUp : BOOL;
    MoveLeft : BOOL;
    MoveRight : BOOL;
    ActivateGrip : BOOL;
    ActivateRelease : BOOL;
END_VAR
VAR
    step : INT := 0;
    executing : BOOL;
    startPrev : BOOL;
    startEdge : BOOL;
END_VAR

pous.implementation:
MoveDown := FALSE;
MoveUp := FALSE;
MoveLeft := FALSE;
MoveRight := FALSE;
ActivateGrip := FALSE;
ActivateRelease := FALSE;
IF NOT EmergencyStop THEN
    executing := FALSE;
    step := 0;
ELSIF ManualMode THEN
    MoveDown := DownButton AND NOT DownLimitSwitch;
    MoveUp := UpButton AND NOT UpLimitSwitch;
    MoveLeft := LeftButton AND NOT LeftLimitSwitch;
    MoveRight := RightButton AND NOT RightLimitSwitch;
    ActivateGrip := GripButton AND NOT GripLimitSwitch;
    ActivateRelease := ReleaseButton AND NOT ReleaseLimitSwitch;
    step := 0;
ELSE
    startEdge := Start AND NOT startPrev;
    IF startEdge THEN
        executing := TRUE;
        IF step >= 8 THEN
            step := 0;
        END_IF
    END_IF
    CASE step OF
    0:
        IF executing THEN
            MoveDown := TRUE;
            IF DownLimitSwitch THEN
                IF SingleStepMode THEN executing := FALSE; END_IF
                step := 1;
            END_IF
        END_IF
    1:
        IF executing THEN
            ActivateGrip := TRUE;
            IF GripLimitSwitch THEN
                IF SingleStepMode THEN executing := FALSE; END_IF
                step := 2;
            END_IF
        END_IF
    2:
        IF executing THEN
            MoveUp := TRUE;
            IF UpLimitSwitch THEN
                IF SingleStepMode THEN executing := FALSE; END_IF
                step := 3;
            END_IF
        END_IF
    3:
        IF executing THEN
            MoveRight := TRUE;
            IF RightLimitSwitch THEN
                IF SingleStepMode THEN executing := FALSE; END_IF
                step := 4;
            END_IF
        END_IF
    4:
        IF executing THEN
            MoveDown := TRUE;
            IF DownLimitSwitch THEN
                IF SingleStepMode THEN executing := FALSE; END_IF
                step := 5;
            END_IF
        END_IF
    5:
        IF executing THEN
            ActivateRelease := TRUE;
            IF ReleaseLimitSwitch THEN
                IF SingleStepMode THEN executing := FALSE; END_IF
                step := 6;
            END_IF
        END_IF
    6:
        IF executing THEN
            MoveUp := TRUE;
            IF UpLimitSwitch THEN
                IF SingleStepMode THEN executing := FALSE; END_IF
                step := 7;
            END_IF
        END_IF
    7:
        IF executing THEN
            MoveLeft := TRUE;
            IF LeftLimitSwitch THEN
                IF SingleStepMode THEN
                    executing := FALSE;
                    step := 0;
                ELSIF SingleCycleMode THEN
                    executing := FALSE;
                    step := 8;
                ELSE
                    step := 0;
                END_IF
            END_IF
        END_IF
    END_CASE
END_IF
startPrev := Start;
